const link = ($json['Job link'] || '').toString().trim();
const details = ($json['Job details / paste text'] || '').toString().trim();
const note = ($json['Source note'] || '').toString().trim();
const parts = [];
if (details) parts.push(details);
if (link) parts.push('Link: ' + link);
if (note) parts.push('Source note: ' + note);
const raw = parts.join('\n');
const hasContent = (details.length + link.length) > 0;
let key = link;
if (!key) { key = details.toLowerCase().replace(/\s+/g, ' ').slice(0, 180); }
key = key.toLowerCase().replace(/^https?:\/\//, '').replace(/\/+$/, '').trim();
return {
  has_content: hasContent,
  raw_text: raw,
  source: 'manual_form',
  source_note: note,
  apply_link: link,
  source_url: link,
  source_id: key,
};
